import * as OurTypes from "../src/types";
import * as TestCommonJsonization from "./commonJsonization";

test("casts over an instance of ReadonlY", () => {
  const theReadonly =
    TestCommonJsonization.loadMinimalReadonly();

  expect(
    OurTypes.isReadonly(theReadonly)
  ).toStrictEqual(true);
  expect(
    OurTypes.asReadonly(theReadonly)
  ).toStrictEqual(theReadonly);

  expect(
    OurTypes.isSomething(theReadonly)
  ).toStrictEqual(false);
  expect(
    OurTypes.asSomething(theReadonly)
  ).toBeNull();
});

test("casts over an instance of Something", () => {
  const theSomething =
    TestCommonJsonization.loadMinimalSomething();

  expect(
    OurTypes.isReadonly(theSomething)
  ).toStrictEqual(false);
  expect(
    OurTypes.asReadonly(theSomething)
  ).toBeNull();

  expect(
    OurTypes.isSomething(theSomething)
  ).toStrictEqual(true);
  expect(
    OurTypes.asSomething(theSomething)
  ).toStrictEqual(theSomething);
});

